const fs=require('node:fs'),vm=require('node:vm');
(async()=>{
const observations=[];
for(const mode of ['CONFIG','APP_CONFIG_LOCAL']){
 const w={dispatchEvent(){}};w[mode]={SUPABASE_URL:'https://example.invalid/rest/v1/',SUPABASE_ANON_KEY:'non-secret-test-key'};
 const s={window:w,fetch:async()=>({ok:false}),console:{log(){},error(){},warn(){}},setTimeout(){},CustomEvent:function(){}};
 await vm.runInNewContext(fs.readFileSync('config.js','utf8'),s);
 observations.push({scenario:'runtime-config-'+mode,url:w.APP_CONFIG.SUPABASE_URL,key_present:!!w.APP_CONFIG.SUPABASE_ANON_KEY});
}
const handlers={};const channel={on(kind,filter,handler){handlers[filter.event]=handler;return this;},subscribe(){return this;},send(){return Promise.resolve();}};
const w={state:{uid:'audit-user',userNickname:'Audit'},getSupabaseClient:()=>({channel:()=>channel})};
const sandbox={window:w,document:{readyState:'loading',addEventListener(){},getElementById(){return null;},querySelector(){return null;}},localStorage:{getItem(){return null;},setItem(){}},console:{log(){},error(){},warn(){}},setTimeout(){},clearTimeout(){},setInterval(){},clearInterval(){},navigator:{}};
vm.createContext(sandbox);
vm.runInContext(fs.readFileSync('guandan-game.js','utf8'),sandbox);
vm.runInContext(fs.readFileSync('guandan-mp-ext.js','utf8'),sandbox);
await w.GD_MP.startNetMatch('GD1234');
for(const event of ['PLAY_CARDS','PASS_TURN']){try{handlers[event]({payload:{}});observations.push({event,error:null});}catch(e){observations.push({event,error:e.name+': '+e.message});}}
handlers.ROOM_SYNC({payload:{seats:[{uid:'audit-user',nickname:'Audit'},null,null,null],countdownSeconds:180,countdownOver:false}});
handlers.GAME_START({payload:{hands:[[{suit:'S',rank:'A'}],[],[],[]],hostTurn:0}});
observations.push({scenario:'guandan-hand-integration',global_hand_length:w.gdPlayerHand.length,core_players_length:w.GD.state.players.length,global_card_has_kind:Object.hasOwn(w.gdPlayerHand[0],'kind'),global_renderer_type:typeof w.renderGameBoard,global_sorter_type:typeof w.sortHandCards});
const goW={};const goS={window:goW,document:{readyState:'loading',addEventListener(){},getElementById(){return null;}},setInterval(){return 1;},clearInterval(){},clearTimeout(){},setTimeout(){},console:{log(){},error(){}}};
const src=fs.readFileSync('multiplayer-ext.js','utf8').replace('window.MP = {','window.__audit = {state, applyRemotePayload, onOpponentMove}; window.MP = {');
vm.runInNewContext(src,goS);
const state=goW.__audit.state;state.blackCaptures=5;state.whiteCaptures=7;goW.state.koPoint={row:2,col:2};goW.MP.startAIGame();
observations.push({scenario:'go-new-ai-game-reset',black_captures:state.blackCaptures,white_captures:state.whiteCaptures,ko_point:goW.state.koPoint});
state.whiteCaptures=0;state.board[1][1]=1;
const payload={row:1,col:2,color:2,captured:[[1,1]],white_captures:1,black_captures:0,next_turn:'black'};
goW.__audit.applyRemotePayload(payload);await goW.__audit.onOpponentMove(payload);
observations.push({scenario:'go-broadcast-capture-count',announced_white_captures:1,actual_white_captures:state.whiteCaptures});
console.log(JSON.stringify(observations,null,2));
})().catch(e=>{console.error(e);process.exitCode=1;});

syntax_probe_script:
const fs=require('node:fs'),cp=require('node:child_process'),vm=require('node:vm');
const files=cp.spawnSync('git',['ls-files'],{encoding:'utf8'}).stdout.trim().split('\n').filter(p=>!p.startsWith('node_modules/'));
const scripts=files.filter(p=>p.endsWith('.js'));
let failed=0;
for(const p of scripts){const r=cp.spawnSync(process.execPath,['--check',p],{encoding:'utf8'});console.log(JSON.stringify({check:'node --check',path:p,exit:r.status,detail:r.status?r.stderr.trim().split('\n').slice(0,9).join('\n'):''}));if(r.status)failed++;}
let inline=0,inlineFailed=0;
for(const p of files.filter(p=>p.endsWith('.html'))){
const re=/<script\b([^>]*)>([\s\S]*?)<\/script>/gi;let m;
while((m=re.exec(fs.readFileSync(p,'utf8')))){if(/\bsrc\s*=/i.test(m[1])||!m[2].trim())continue;inline++;try{new vm.Script(m[2],{filename:p+':inline-'+inline});}catch(e){inlineFailed++;console.log(JSON.stringify({check:'inline-script-parse',path:p,error:e.message}));}}
}
console.log(JSON.stringify({external_scripts:scripts.length,external_passed:scripts.length-failed,external_failed:failed,inline_scripts:inline,inline_passed:inline-inlineFailed,inline_failed:inlineFailed}));
process.exitCode=failed||inlineFailed?1:0;
